  if(!sharedGameRoute||sharedGameAccess!=='owner'||!game||game.id!==sharedGameRoute.gameId)return
  const timer=window.setTimeout(()=>{void updateGameState(game.id,{inning,half:half==='表'?'top':'bottom',balls,strikes,outs,away_score:awayScore,home_score:homeScore})},250)
