 const changeHalf=()=>{const nextHalf=half==='表'?'裏':'表',nextInning=half==='裏'?inning+1:inning;if(half==='裏')setInning(nextInning);setHalf(nextHalf);setOuts(0);resetCount();setRunners({});setPlays(items=>[`${nextInning}回${nextHalf}`,...items])}
