 const detail=(pos:string)=>{const text=`${pos}${resultType}`;if(resultType==='安打')hit(1,text);else if(resultType==='2塁打')hit(2,text);else if(resultType==='3塁打')hit(3,text);else out(text)}
 const updateTeam=(which:'away'|'home',value:Team)=>{if(which==='away')setAway(value);else setHome(value);if(game)setGameTeams(cache=>({...cache,[game.id]:{away:which==='away'?value:(cache[game.id]?.away??away),home:which==='home'?value:(cache[game.id]?.home??home)}}))}; const team=(which:'away'|'home')=>which==='away'?away:home
 const move=(to:'away'|'home',area:'players'|'bench',index:number)=>{if(!drag)return;const from=team(drag.team), dest=team(to),fromKey=drag.area, destKey=area;const fromList=[...from[fromKey]], [player]=fromList.splice(drag.index,1);const destList=drag.team===to&&fromKey===destKey?fromList:[...dest[destKey]];destList.splice(index,0,player);if(drag.team===to)updateTeam(to,{...from,[fromKey]:fromList,[destKey]:destList});else{updateTeam(drag.team,{...from,[fromKey]:fromList});updateTeam(to,{...dest,[destKey]:destList})}setDrag(null)}
 const selectMember=(member:Member)=>{if(!pick)return;const target=team(pick.team),key=pick.area,list=[...target[key]],old=list[pick.index],players=[...target.players],bench=[...target.bench],sourcePlayers=players.findIndex(player=>player.id===member.id),sourceBench=bench.findIndex(player=>player.id===member.id);if(sourcePlayers>=0)players[sourcePlayers]={id:`slot-${Date.now()}`,last:'未設定',first:'',pos:players[sourcePlayers].pos,avg:'---'};if(sourceBench>=0)bench.splice(sourceBench,1);if(key==='players')players[pick.index]={...member,pos:old.pos,avg:old.avg};else bench[pick.index]={...member,pos:old.pos,avg:old.avg};updateTeam(pick.team,{...target,players,bench});setPick(null)}
 const changePosition=(which:'away'|'home',area:'players'|'bench',i:number,pos:string)=>{const t=team(which),list=[...t[area]];list[i]={...list[i],pos};updateTeam(which,{...t,[area]:list})}
 const addPlayer=(which:'away'|'home')=>{const t=team(which),player:Player={id:`slot-${Date.now()}-${which}`,last:'選択してください',first:'',pos:'打',avg:'---'};updateTeam(which,{...t,players:[...t.players,player]});setPick({team:which,area:'players',index:t.players.length})}
 const dropOnField=(pos:string)=>{if(!drag||drag.team!=='home')return;if(drag.area==='players'){const players=[...home.players],target=players.findIndex(player=>player.pos===pos);if(target>=0){[players[drag.index].pos,players[target].pos]=[players[target].pos,players[drag.index].pos];updateTeam('home',{...home,players})}}else{const bench=[...home.bench],[incoming]=bench.splice(drag.index,1);if(!incoming)return;const players=[...home.players],target=players.findIndex(player=>player.pos===pos);if(target>=0){const [outgoing]=players.splice(target,1);bench.push(outgoing)}players.push({...incoming,pos});updateTeam('home',{...home,players,bench})}setDrag(null)}
