 const openGame=(selected:Game)=>{if(selectedRoom){openSharedGame({roomId:selectedRoom.id,gameId:selected.id});return}const saved=gameTeams[selected.id],nextAway=saved?.away??makeTeam(selected.away,0,selected.awayColor??pastelColors[0]),nextHome=saved?.home??makeTeam(selected.home,9,selected.homeColor??pastelColors[1]);setGame(selected);setAway(nextAway);setHome(nextHome);setGameTeams(cache=>cache[selected.id]?cache:{...cache,[selected.id]:{away:nextAway,home:nextHome}});setAwayScore(selected.awayScore??0);setHomeScore(selected.homeScore??0);setView('game')}
 const createGame=async(input:GameCreationInput)=>{const created=await createOwnedGame(input),added:Game={id:created.game.id,title:created.game.title,status:created.game.status,away:created.game.away.name,home:created.game.home.name,awayScore:0,homeScore:0,awayColor:created.game.away.color,homeColor:created.game.home.color},nextAway=emptyTeam(added.away,created.game.away.color),nextHome=emptyTeam(added.home,created.game.home.color);setGames(g=>[...g,added]);setSelectedRoom(current=>({id:created.room.id,name:created.room.name,roomNumber:created.room.roomNumber,teams:current?.id===created.room.id?current.teams:[],games:[...(current?.id===created.room.id?current.games:[]),created.game]}));setAway(nextAway);setHome(nextHome);setGameTeams(cache=>({...cache,[added.id]:{away:nextAway,home:nextHome}}));setInning(1);setHalf('表');setBalls(0);setStrikes(0);setOuts(0);setAwayScore(0);setHomeScore(0);setRunners({});setResult('');setResultType(null);setHistory([]);setPlays(['1回表']);setBatter(0);setCreating(false);setGame(added);openSharedGame({roomId:created.room.id,gameId:created.game.id})}
