 if(view==='room-games'&&selectedRoom){const roomGames:Game[]=selectedRoom.games.map(selected=>({id:selected.id,title:selected.title,status:selected.status,away:selected.away.name,home:selected.home.name,awayScore:selected.away.score,homeScore:selected.home.score,awayColor:selected.away.color,homeColor:selected.home.color}));return <Home games={roomGames} room={selectedRoom} admin={admin} members={members} rosterOpen={rosterOpen} newMember={newMember} roomName={selectedRoom.name} roomNumber={selectedRoom.roomNumber} onBack={()=>setView('mypage')} onRoster={()=>setRosterOpen(v=>!v)} onNewMember={(value:{last:string;first:string})=>setNewMember(value)} onAddMember={()=>{if(newMember.last){setMembers(m=>[...m,{id:`m${Date.now()}`,last:newMember.last,first:newMember.first}]);setNewMember({last:'',first:''})}}} onEditMember={(id:string)=>{const member=members.find(item=>item.id===id);if(!member)return;const value=window.prompt('苗字 名前を入力',`${member.last} ${member.first}`);if(value){const [last,first='']=value.split(/\s+/);setMembers(list=>list.map(item=>item.id===id?{...item,last,first}:item))}}} onRemoveMember={(id:string)=>setMembers(list=>list.filter(item=>item.id!==id))} onOpen={openGame} onAdd={()=>setCreating(true)} onLogout={()=>setLogoutOpen(true)} creating={creating} setup={setup} setSetup={setSetup} onCreate={createGame} onCancel={()=>setCreating(false)} passwordOpen={false} onClosePassword={()=>setPasswordOpen(false)} logoutOpen={logoutOpen} onLogoutConfirm={()=>void logout()} onCloseLogout={()=>setLogoutOpen(false)}/>}
